void update_gpu_info(const GPUInfo *gpu_info) {
    // Lock access to the GPU information
    lock_gpu_info();

    // Attempt to merge the new GPU info with existing data
    if (merge_gpu_info(gpu_info)) {
        // Trigger callbacks for GPU info updates
        trigger_gpu_info_callbacks();

        // Update the GPU information in the content client
        update_content_client_gpu_info(gpu_info);

        // Refresh GPU feature flags
        refresh_gpu_feature_flags();
    }

    // Unlock access to the GPU information
    unlock_gpu_info();
}

